import type { SymbolContent, SymbolLanguage } from '@/lib/symbolTypes';
import { readSymbolContentAsset } from '@/services/symbolContentAsset';

export type SymbolContentMap = Record<string, SymbolContent>;

// Generated by scripts/sync-app-symbol-dictionary.js. JSON under an asset
// extension: Metro copies the files into the app instead of compiling every
// language into the JavaScript bundle, and only the reader's language is read.
const SOURCES: Record<SymbolLanguage, number> = {
  /* eslint-disable @typescript-eslint/no-require-imports */
  en: require('@/data/app/symbol-content/en.txt'),
  fr: require('@/data/app/symbol-content/fr.txt'),
  es: require('@/data/app/symbol-content/es.txt'),
  de: require('@/data/app/symbol-content/de.txt'),
  it: require('@/data/app/symbol-content/it.txt'),
  pt: require('@/data/app/symbol-content/pt.txt'),
  /* eslint-enable @typescript-eslint/no-require-imports */
};

const loaded = new Map<SymbolLanguage, SymbolContentMap>();
const pending = new Map<SymbolLanguage, Promise<SymbolContentMap>>();

function isContentMap(value: unknown): value is SymbolContentMap {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  return Object.values(value).every(
    (entry) => !!entry && typeof (entry as SymbolContent).shortDescription === 'string'
      && Array.isArray((entry as SymbolContent).askYourself),
  );
}

async function read(language: SymbolLanguage): Promise<SymbolContentMap> {
  const data: unknown = JSON.parse(await readSymbolContentAsset(SOURCES[language]));
  if (!isContentMap(data)) throw new Error(`Unexpected symbol content for ${language}`);
  loaded.set(language, data);
  return data;
}

/** Content already read, so a revisited screen renders it on its first pass. */
export function peekSymbolContent(language: SymbolLanguage): SymbolContentMap | undefined {
  return loaded.get(language);
}

/**
 * Short descriptions and questions for one language, read once from the
 * bundled asset. It ships with the app or the update, so it works offline.
 */
export function loadSymbolContent(language: SymbolLanguage): Promise<SymbolContentMap> {
  const inMemory = loaded.get(language);
  if (inMemory) return Promise.resolve(inMemory);

  let request = pending.get(language);
  if (!request) {
    request = read(language).finally(() => pending.delete(language));
    pending.set(language, request);
  }
  return request;
}
